//! Wire examples generated by C against checksum-pinned upstream ath10k declarations.
//! Regenerate with tools/check-wifi-abi.py; never derive expected bytes from Rust encoders.
use osel_core::wifi::{htc, htt, ieee80211, station, wmi};

const AP: [u8; 6] = [2, 3, 4, 5, 6, 7];
const STA: [u8; 6] = [2, 3, 4, 5, 6, 8];
macro_rules! fixture {
    ($name:literal) => {
        include_bytes!(concat!("fixtures/ath10k-v6.12/", $name, ".bin"))
    };
}

fn ap() -> ieee80211::AccessPoint {
    let mut frame = vec![0; 36];
    frame[0] = 0x80;
    frame[16..22].copy_from_slice(&AP);
    frame[32] = 100;
    frame[34] = 0x11;
    frame.extend_from_slice(b"\x00\x04OSel\x01\x04\x82\x84\x8b\x96");
    frame.extend_from_slice(&ieee80211::RSN_IE);
    ieee80211::beacon(&frame, 2412, -50).unwrap()
}

#[test]
fn firmware_boot_abi_matches_c_service_ready_init_and_ready() {
    let mut service = wmi::service_ready(fixture!("service-ready")).unwrap();
    assert_eq!(service.build, 0x441a8135);
    assert_eq!(service.chains, 2);
    assert_eq!(service.tx_power, [3, 30]);
    assert_eq!(service.eeprom_domain, 0x6c);
    assert!(service.supports(65));
    assert_eq!(service.requests.len(), 1);
    let command = wmi::init(
        &service,
        &[wmi::MemoryChunk {
            id: 1,
            address: 0x1000,
            length: 34 * 32,
        }],
    )
    .unwrap();
    assert_eq!(command, fixture!("init"));
    assert_eq!(wmi::ready(fixture!("ready")), Ok(STA));
    let capabilities = fixture!("management-services");
    for (index, service_id) in [wmi::MGMT_TX_HTT, wmi::MGMT_TX_WMI].into_iter().enumerate() {
        assert_eq!(
            u32::from_le_bytes(capabilities[index * 4..index * 4 + 4].try_into().unwrap()) as usize,
            service_id
        );
        assert!(!service.supports(service_id));
        service.services[service_id / 4] |= 1 << (service_id % 4);
        assert!(service.supports(service_id));
    }
}

#[test]
fn runtime_radio_chains_match_c_and_stop_on_invalid_capabilities_or_send_failure() {
    let expected = [
        fixture!("runtime-tx-chains").as_slice(),
        fixture!("runtime-rx-chains").as_slice(),
    ];
    let service = wmi::service_ready(fixture!("service-ready")).unwrap();
    let mut sent = Vec::new();
    assert_eq!(
        wmi::station::configure_chains(service.chains, |command| {
            sent.push(command.to_vec());
            Ok(())
        }),
        Ok(3)
    );
    assert_eq!(sent, expected);
    for chains in [0, 5, 32, u32::MAX] {
        assert!(
            wmi::station::configure_chains(chains, |_| {
                panic!("invalid RF capability must fail before any command")
            })
            .is_err()
        );
    }
    for failure in 0..expected.len() {
        let mut attempted = 0;
        assert_eq!(
            wmi::station::configure_chains(service.chains, |command| {
                assert_eq!(command, expected[attempted]);
                attempted += 1;
                if attempted == failure + 1 {
                    Err(osel_core::errno::Errno::EIO)
                } else {
                    Ok(())
                }
            }),
            Err(osel_core::errno::Errno::EIO)
        );
        assert_eq!(attempted, failure + 1);
    }
    for (chains, mask) in [(1, 1u32), (2, 3), (3, 7), (4, 15)] {
        let mut sent = 0;
        assert_eq!(
            wmi::station::configure_chains(chains, |command| {
                let mut expected = expected[sent].to_vec();
                expected[12..16].copy_from_slice(&mask.to_le_bytes());
                assert_eq!(command, expected);
                sent += 1;
                Ok(())
            }),
            Ok(mask)
        );
        assert_eq!(sent, 2);
    }
}

