#[test]
fn repeated_scans_accumulate_beacons_and_distinguish_empty_and_rejected_frames() {
    let mut results = wmi::ScanResults::default();
    assert!(results.event(fixture!("scan-completed"), 0xa001).unwrap());
    assert!(results.networks.iter().all(Option::is_none));
    assert!(!results.event(fixture!("beacon"), 0xa002).unwrap());
    assert!(!results.event(fixture!("beacon"), 0xa002).unwrap());
    let mut completed = fixture!("scan-completed").to_vec();
    completed[24..28].copy_from_slice(&0xa002u32.to_le_bytes());
    assert!(results.event(&completed, 0xa002).unwrap());
    assert!(results.event(&completed, 0xa003).is_err());
    completed[24..28].copy_from_slice(&0xa003u32.to_le_bytes());
    assert!(results.event(&completed, 0xa003).unwrap());
    assert_eq!(results.networks.iter().flatten().count(), 1);
    assert_eq!(results.networks[0], Some(ap()));
    assert_eq!(results.beacons, 2);
    let mut bad = fixture!("beacon").to_vec();
    bad[28] = 1; // CRC error in WMI metadata
    results.event(&bad, 0xa003).unwrap();
    let mut bad = fixture!("beacon").to_vec();
    bad[52 + 37] = 255; // SSID overruns the management frame
    results.event(&bad, 0xa003).unwrap();
    assert_eq!(results.management, 4);
    assert_eq!(results.bad_management, 1);
    assert_eq!(results.bad_beacons, 1);
    assert_eq!(results.networks[0], Some(ap()));
}

#[test]
fn unsupported_networks_explain_security_band_and_rate_rejections_without_weakening_admission() {
    let good = ap();
    assert_eq!(station::unsupported_reason(&good), None);
    let mut cases = Vec::new();
    let mut network = good;
    network.rsn = None;
    cases.push((network, "no WPA2 RSN; WPA1/WEP unsupported"));
    let mut network = good;
    network.rsn.as_mut().unwrap().group_ccmp = false;
    cases.push((network, "group cipher requires CCMP/AES"));
    let mut network = good;
    network.rsn.as_mut().unwrap().pairwise_ccmp = false;
    cases.push((network, "pairwise cipher requires CCMP/AES"));
    let mut network = good;
    network.rsn.as_mut().unwrap().psk = false;
    cases.push((network, "WPA2-Personal PSK required"));
    let mut network = good;
    network.rsn.as_mut().unwrap().pmf_required = true;
    cases.push((network, "mandatory PMF unsupported"));
    let mut network = good;
    network.frequency = 5180;
    cases.push((network, "connection requires channels 1-11"));
    let mut network = good;
    network.frequency = 2472;
    cases.push((network, "connection requires channels 1-11"));
    let mut network = good;
    network.capabilities &= !0x10;
    cases.push((network, "open network; WPA2 required"));
    let mut network = good;
    network.unsupported_basic_rate = true;
    cases.push((network, "unsupported basic rates"));
    for (network, reason) in cases {
        assert_eq!(station::unsupported_reason(&network), Some(reason));
        assert!(station::supported(&network).is_err());
        assert!(wmi::station::start(&network).is_err());
        assert!(
            wmi::station::start_with_channel(&network, 0x6c, |_| {
                panic!("unsupported AP must not publish a transmit channel")
            })
            .is_err()
        );
        assert!(station::associate(STA, &network, 0).is_err());
    }
}

#[test]
fn c_management_events_cover_scan_authentication_and_association() {
    assert_eq!(wmi::scan_complete(fixture!("scan-completed")), Ok(true));
    assert_eq!(wmi::station::started(fixture!("vdev-started")), Ok(()));
    let frame = wmi::management(fixture!("beacon")).unwrap();
    assert_eq!(frame.frequency, 2412);
    assert_eq!(frame.rssi, -50);
    assert_eq!(
        ieee80211::beacon(frame.frame, frame.frequency, frame.rssi).unwrap(),
        ap()
    );
    let auth = wmi::management(fixture!("authenticated")).unwrap();
    assert!(matches!(
        station::response(auth.frame, STA, AP),
        Ok(station::Response::Authenticated)
    ));
    let assoc = wmi::management(fixture!("associated")).unwrap();
    assert!(matches!(
        station::response(assoc.frame, STA, AP),
        Ok(station::Response::Associated(0x123))
    ));
    for packet in [
        fixture!("vdev-started").as_slice(),
        fixture!("scan-completed").as_slice(),
    ] {
        let mut bad = packet.to_vec();
        // Status/reason is the last word of vdev start, the second scan word.
        let offset = if packet == fixture!("vdev-started") {
            20
        } else {
            12
        };
        bad[offset] = 1;
        if offset == 20 {
            assert!(wmi::station::started(&bad).is_err());
        } else {
            assert!(wmi::scan_complete(&bad).is_err());
        }
    }
}

#[test]
fn pdev_tx_counters_use_the_original_tlv_layout_and_reject_incomplete_snapshots() {
    assert_eq!(
        wmi::station::request_tx_stats().unwrap(),
        fixture!("request-pdev-stats")
    );
    assert_eq!(fixture!("pdev-stats-layout"), &[180, 0, 0, 0, 28, 0, 0, 0]);
    let event = fixture!("pdev-tx-stats");
    let stats = wmi::station::tx_stats(event).unwrap().unwrap();
    assert_eq!(stats.power, 0x10);
    assert_eq!(stats.counters, core::array::from_fn(|i| 0x11 + i as u32));
    for length in 0..event.len() {
        assert!(wmi::station::tx_stats(&event[..length]).is_err());
    }
    let mut no_pdev = event[..52].to_vec();
    no_pdev[12..16].fill(0); // num_pdev_stats
    no_pdev[48..50].fill(0); // empty ARRAY_BYTE
    assert_eq!(wmi::station::tx_stats(&no_pdev), Ok(None));
    for count in [2u32, u32::MAX] {
        let mut bad = event.to_vec();
        bad[12..16].copy_from_slice(&count.to_le_bytes());
        assert!(wmi::station::tx_stats(&bad).is_err());
    }
    for duplicate in [&event[4..48], &event[48..]] {
        let mut bad = event.to_vec();
        bad.extend_from_slice(duplicate);
        assert!(wmi::station::tx_stats(&bad).is_err());
    }
    assert!(wmi::station::tx_stats(&event[..48]).is_err()); // no ARRAY_BYTE
    let mut no_header = event[..4].to_vec();
    no_header.extend_from_slice(&event[48..]);
    assert!(wmi::station::tx_stats(&no_header).is_err());
    let mut wrong_id = event.to_vec();
    wrong_id[0] ^= 1;
    assert!(wmi::station::tx_stats(&wrong_id).is_err());
}

