#[test]
fn only_the_associated_authenticator_can_feed_eapol_before_and_after_authorization() {
    let mut bytes = fixture!("encrypted-ethernet").to_vec();
    bytes[312..314].copy_from_slice(&[0x88, 0x8e]);
    for authorized in [false, true] {
        let frame = htt::receive(&bytes, 14, STA, AP).unwrap();
        assert!(htt::ethernet_allowed(&frame, STA, AP, authorized));
        // Valid encrypted traffic relayed by the AP can have another Ethernet
        // source. That source still must not act as the WPA2 authenticator.
        let mut relayed = bytes.clone();
        relayed[252] ^= 2; // 802.11 address 3
        relayed[306] ^= 2; // matching Ethernet source
        let frame = htt::receive(&relayed, 14, STA, AP).unwrap();
        assert!(!htt::ethernet_allowed(&frame, STA, AP, authorized));
    }
    let encrypted = htt::receive(fixture!("encrypted-ethernet"), 14, STA, AP).unwrap();
    assert!(!htt::ethernet_allowed(&encrypted, STA, AP, false));
    assert!(htt::ethernet_allowed(&encrypted, STA, AP, true));
    let unencrypted = htt::Received {
        encrypted: false,
        ..encrypted
    };
    assert!(!htt::ethernet_allowed(&unencrypted, STA, AP, true));
}

#[test]
fn single_bit_mutations_of_structured_events_remain_bounded() {
    let original = fixture!("pdev-tx-stats");
    for offset in 0..original.len() {
        for bit in 0..8 {
            let mut bytes = original.to_vec();
            bytes[offset] ^= 1 << bit;
            let _ = wmi::station::tx_stats(&bytes);
        }
    }
    let original = fixture!("service-ready");
    for offset in 0..original.len() {
        for bit in 0..8 {
            let mut bytes = original.to_vec();
            bytes[offset] ^= 1 << bit;
            let _ = wmi::service_ready(&bytes);
        }
    }
    let original = fixture!("encrypted-ethernet");
    for offset in 0..original.len() {
        for bit in 0..8 {
            let mut bytes = original.to_vec();
            bytes[offset] ^= 1 << bit;
            let _ = htt::receive(&bytes, 14, STA, AP);
        }
    }
}

#[test]
fn truncated_c_events_never_become_ready_or_release_owned_dma() {
    for packet in [
        fixture!("peer-map").as_slice(),
        fixture!("security").as_slice(),
    ] {
        for end in 0..packet.len() {
            assert!(htt::event(&packet[..end]).is_err());
        }
    }
    let packet = fixture!("service-ready");
    for end in 0..packet.len() {
        assert!(wmi::service_ready(&packet[..end]).is_err());
    }
    let packet = fixture!("htt-version-with-credits");
    for end in 0..packet.len() {
        assert!(htc::credits(&packet[..end], 2).is_err());
    }
}

#[test]
fn hostile_wire_inputs_are_bounded_and_never_panic() {
    let mut random = 0x6174_32aa_0807_11adu64;
    for length in 0..384 {
        for _ in 0..16 {
            let mut bytes = vec![0; length];
            for byte in &mut bytes {
                random ^= random << 13;
                random ^= random >> 7;
                random ^= random << 17;
                *byte = random as u8;
            }
            let _ = htc::payload(&bytes);
            let _ = htc::credits(&bytes, 2);
            let _ = htc::ready(&bytes);
            let _ = htt::event(&bytes);
            let _ = htt::receive(&bytes, length, STA, AP);
            let _ = htt::offload_eapol(&bytes, 7, STA, AP);
            let _ = wmi::service_ready(&bytes);
            let _ = wmi::ready(&bytes);
            let _ = wmi::management(&bytes);
            let _ = wmi::scan_complete(&bytes);
            let _ = wmi::station::started(&bytes);
            let _ = wmi::station::tx_stats(&bytes);
            let _ = wmi::station::lost(&bytes, AP);
            let _ = ieee80211::beacon(&bytes, 2412, -50);
            let _ = ieee80211::rsn(&bytes);
            let _ = station::response(&bytes, STA, AP);
        }
    }
}
